                    "type": "string"
                },
                "newsletter_send_id": {
                    "type": "string"
                },
                "newsletter_user_list_id": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "sg_event_id": {
            "description": "A unique ID to this event that you can use for deduplication purposes. These IDs are up to 100 characters long and are URL safe.",
            "maxLength": 4096,
            "minLength": 22,
            "type": "string"
        },
